{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Ensure that key vault secrets have 'content_type' set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The 'content_type' attribute is not set for the key vault secret. This attribute helps to identify the type of the secret, which can aid in its interpretation and usage."
    },
    {
      "check_id": "CKV_AZURE_41",
      "title": "Ensure that the expiration date is set on all secrets",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret does not have an expiration date set. Without an expiration date, secrets may remain valid indefinitely, increasing the risk of misuse if they are not rotated or deleted in a timely manner."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  content_type = \"application/json\"\n  expiration_date = \"2024-12-31T23:59:59Z\"\n  depends_on = [azurerm_mssql_database.legal_metadata_db]\n}",
  "fix_summary": "Added 'content_type' to specify the type of the secret and 'expiration_date' to ensure the secret has a defined validity period."
}
